:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) input:not([type]):not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)),
