:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) .menu_button:not(.mes_edit_buttons *):not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  background-color: var(--ui-color-sec);
