  span {
  filter: none !important;
}

.fa-solid:not(#load-spinner) {
  font-size: var(--icon-size);
  text-shadow: none !important;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) select:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  background-color: var(--ui-color-sec) !important;
  color: var(--text-color-main);
  border: none !important;
  margin: calc(var(--mainFontSize) * 0.3) 0 !important;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) select option:not(:checked):not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  color: var(--text-color-sec);
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) select option:checked:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  color: var(--ui-color-sec);
  background-color: var(--text-color-main) !important;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) select option:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  background-color: var(--ui-color-sec) !important;
}

.ui-widget-content .ui-state-active {
  color: var(--theme-color-1) !important;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) input[type="checkbox"]:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  width: calc(var(--mainFontSize) * 0.9);
  height: calc(var(--mainFontSize) * 0.9);
  border: none;
  outline: none;
  background-color: var(--ui-color-main);
  filter: none;
  box-shadow: 0 0 0 1px var(--text-color-sec);
  transform: translateY(0);
  margin-left: 1px;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) input[type="checkbox"]:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *))::before {
  box-shadow: inset 1em 1em var(--theme-color-1);
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) input[type="checkbox"].del_checkbox:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
