/* Dream · 夏日像素明信片 */
:root {
  --dream-paper:#fff9ec; --dream-ink:#203e58; --dream-muted:#486678;
  --dream-blue:#b9e9f6; --dream-pink:#ffcedb; --dream-line:#477b91;
  --dream-rose:#a52d58; --dream-mint:#bcebd6;
  --border-radius-small:0px; --border-radius-medium:0px; --box-border-radius:0px;
  --ui-color-main:var(--dream-paper); --ui-color-sec:#e5f2ed;
  --text-color-main:var(--dream-ink); --text-color-sec:var(--dream-muted);
  --theme-color-1:#24637c; --theme-color-2:var(--dream-rose);
  --gradient-main:linear-gradient(90deg,#ffcedb 0 50%,#b9e9f6 50% 100%);
  --chat-background-color:transparent; --scroll-width:8px;
  --dream-user-stamp:url("https://cdn.jsdelivr.net/gh/dreamdana88/picture@main/summer-postcard/assets/user-stamp.svg"); --dream-bot-stamp:url("https://cdn.jsdelivr.net/gh/dreamdana88/picture@main/summer-postcard/assets/bot-stamp.svg");
}

body {text-shadow:none!important; color:var(--dream-ink);}

#bg1 {background-image:url("https://cdn.jsdelivr.net/gh/dreamdana88/picture@main/summer-postcard/assets/summer-desktop.webp")!important; background-position:center!important; background-size:cover!important;}

:root {--dream-content-width:min(58vw,920px);}
@media(min-width:1001px) {

:root {--sheldWidth:var(--dream-content-width)!important;}

#sheld,#top-bar,#top-settings-holder {width:var(--dream-content-width)!important;max-width:920px!important;}

#left-nav-panel,#right-nav-panel {width:calc((100vw - var(--dream-content-width))/2)!important;max-width:none!important;}

#left-nav-panel {left:0!important;right:auto!important;}

#right-nav-panel {left:auto!important;right:0!important;}
}

#chat {padding:12px 8px!important; gap:16px; background:transparent!important; backdrop-filter:none!important;}

#chat > .mes:not(.smallSysMes) {
  --dream-stamp:var(--dream-bot-stamp);
  display:grid!important; grid-template-columns:minmax(0,1fr); align-items:stretch;
  width:100%!important; padding:0!important; margin:0!important;
  backdrop-filter:none!important; isolation:isolate; min-width:0;
}

#chat > .mes[is_user="true"]:not(.smallSysMes) {--dream-stamp:var(--dream-user-stamp);}

#chat > .mes:not(.smallSysMes) > .mes_block {display:contents!important;}

#chat .mesAvatarWrapper :is(.mesIDDisplay,.mes_timer,.tokenCounterDisplay) {display:contents;}

#chat .mes_buttons {opacity:1;flex-wrap:wrap;gap:8px;max-width:100%;}

#chat .mes_button {color:var(--dream-ink);text-shadow:none;}

#chat .mes_edit_buttons {flex-wrap:wrap;max-width:100%;}

#chat .mes_block > :is(.mes_text,.mes_reasoning_details,.mes_media_wrapper,.mes_file_wrapper,.mes_bias) {grid-column:1/-1;min-width:0;max-width:100%;}

#chat .mes_block > .mes_text {font-size:18px!important;line-height:1.62!important;font-family:"Microsoft YaHei","PingFang SC","Noto Sans CJK SC",sans-serif;
  color:var(--dream-ink)!important; padding:14px 12px 16px!important;overflow-wrap:anywhere;text-shadow:none!important;}

#chat .last_mes .mes_block > .mes_text {padding-bottom:54px!important;}

#chat .mes_text :is(p,li,blockquote) {font-size:inherit;line-height:inherit;}

#chat .mes_text p {margin:0 0 .82em;}

#chat .mes_text p:last-child {margin-bottom:0;}

#chat .mes_text :is(strong,u) {color:var(--dream-rose);}

#chat .mes_text em {color:#985720;background:linear-gradient(transparent 58%,rgba(255,220,120,.4) 58%);}

#chat .mes_text q {color:#65429a;font-weight:500;background:rgba(222,208,242,.3);border-radius:2px;}

#chat .mes_text blockquote {margin:1em 0;padding:8px 14px;border-left:4px solid #9474ba;background:#f4f0fb;color:#65429a;}

#chat .mes_text a {color:#a52d58;text-decoration:underline;text-underline-offset:3px;}

#chat .mes_text pre {max-width:100%;overflow-x:auto;white-space:pre;font-size:16px;border:2px solid var(--dream-line);border-radius:0;background:#edf5f3;color:var(--dream-ink);}

#chat .mes_text code {font-size:.9em;}

#chat .mes_text img {max-width:100%;height:auto;}

#chat .mes_text table {display:block;max-width:100%;overflow:auto;}

#chat .mes_reasoning_details {margin:12px; background:#edf5f3;border:2px solid var(--dream-line);border-radius:0;}

#chat .mes_reasoning {font-size:17px;line-height:1.62;}

#chat .mes.selected {outline:4px solid var(--dream-rose)!important;outline-offset:-4px;}

#chat .mes .edit_textarea {font-size:18px!important;line-height:1.62!important;min-height:160px;}

#chat .smallSysMes {background:var(--dream-paper)!important;padding:12px!important;color:var(--dream-ink);border:2px solid var(--dream-line)!important;}

#chat .swipe_left,#chat .swipeRightBlock {z-index:2;color:var(--dream-ink);}

#top-bar,#top-settings-holder {background:var(--dream-paper)!important;box-shadow:0 3px 0 var(--dream-line)!important;backdrop-filter:none!important;}

#send_form {background:var(--dream-paper)!important;border:2px solid var(--dream-line)!important;border-radius:0!important;box-shadow:4px 4px 0 var(--dream-line)!important;backdrop-filter:none!important;}

#send_textarea {font-size:18px!important;line-height:1.5!important;background:var(--dream-paper)!important;color:var(--dream-ink)!important;border:0!important;border-radius:0!important;}

#send_but,#options_button,#extensionsMenuButton,.mes_stop {color:var(--dream-ink)!important;text-shadow:none!important;}

:is(.drawer-content,#left-nav-panel,#right-nav-panel,.popup,#options,#extensionsMenu,.list-group,.floating_panel) {
  background:var(--dream-paper)!important;background-image:none!important;color:var(--dream-ink)!important;
  border:2px solid var(--dream-line)!important;border-radius:0!important;box-shadow:4px 4px 0 var(--dream-line)!important;backdrop-filter:none!important;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) :is(.menu_button,.menu_button_icon,.paginationjs-page,.paginationjs-prev,.paginationjs-next):not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  border-radius:0!important;background-image:none!important;background-color:var(--dream-blue)!important;color:var(--dream-ink)!important;
  border:2px solid var(--dream-line)!important;box-shadow:2px 2px 0 var(--dream-line)!important;text-shadow:none!important;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) :is(.menu_button,.menu_button_icon):hover:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {background-color:var(--dream-mint)!important;}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) :is(.menu_button,.menu_button_icon):active:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {box-shadow:none!important;}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) :is(.menu_button,.menu_button_icon):disabled:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {opacity:.55;}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) :is(input:not([type=checkbox]):not([type=range]):not([type=color]),textarea,select,.text_pole):not(.mes_text *):not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {
  border-radius:0!important;background:var(--dream-paper)!important;color:var(--dream-ink)!important;border:2px solid var(--dream-line)!important;box-shadow:none!important;
}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) :is(input,textarea,select,.menu_button,a):focus-visible:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {outline:3px solid var(--dream-rose)!important;outline-offset:2px;}

:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) input[type=checkbox]:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)),
:where(#left-nav-panel,#right-nav-panel,#top-settings-holder,#send_form,#options,#extensionsMenu,#dialogue_popup,#world_popup,#chat .mes_edit_buttons) input[type=range]:not(:where(#extensions_settings *,#extensions_settings2 *, .mes_text *)) {accent-color:#a52d58;}

:is(.character_select,.group_select,.world_entry,.inline-drawer-header) {border-radius:0!important;background-image:none!important;}

:is(.character_select,.group_select):hover {background:var(--dream-mint)!important;}

:is(.character_select,.group_select) .avatar {border-radius:0!important;border:2px solid var(--dream-line);box-shadow:2px 2px 0 var(--dream-line);}

:is(.character_select,.group_select) .avatar img {border-radius:0!important;}

.inline-drawer-header {border-left:4px solid var(--dream-rose)!important;border-image:none!important;}

.standoutHeader strong::before,#right-nav-panel h2::before,.drawer-content h3.margin0::before {content:"▪";background:none;color:var(--dream-rose);}

::-webkit-scrollbar-thumb {border-radius:0!important;background:#5097ad!important;border:2px solid var(--dream-paper)!important;box-shadow:none!important;}

