/* Startup postcard. The standalone copy in public/css/user.css also covers the first frame. */
#preloader {
  background:linear-gradient(150deg,#d9f1fb,#f6fbff 58%,#fbe8f0)!important;
  backdrop-filter:none!important;
  -webkit-backdrop-filter:none!important;
}

#preloader::before {
  content:"正在初始化…";
  position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);
  box-sizing:border-box;width:min(84vw,520px);height:260px;
  padding:170px 24px 20px;text-align:center;
  font:500 16px/1.5 "Microsoft YaHei",sans-serif;
  letter-spacing:.06em;color:#3d6880;
  background:
    repeating-linear-gradient(0deg,rgba(116,174,208,.06) 0 2px,transparent 2px 11px),
    repeating-linear-gradient(90deg,rgba(116,174,208,.06) 0 2px,transparent 2px 11px),
    rgba(255,255,255,.86);
  border:3px dashed rgba(255,255,255,.96);border-radius:15px;
  box-shadow:0 7px 24px rgba(61,125,157,.17),inset 0 0 0 1px rgba(104,167,197,.25);
}

#preloader::after {
  content:"";position:absolute;left:calc(50% - 19px);top:calc(50% - 53px);transform:scale(2);
  width:38px;height:38px;
  background-image:var(--dream-topbar-icons);background-size:177.175px 80.275px;
  background-position:-91px -2px;background-repeat:no-repeat;image-rendering:pixelated;
  mix-blend-mode:multiply;
}

